// Original phosphor radar treatment inspired by early tactical console HUDs.
export function createSpawnMap({combat,actors,objectives,world,spawns,onOpen=()=>{}}){
 const radar=document.createElement('button');radar.id='battle-radar';radar.innerHTML='<b>M · RADAR / SPAWN</b><canvas width="240" height="170"></canvas>';radar.hidden=true;
 const panel=document.createElement('section');panel.id='spawn-map';panel.hidden=true;panel.innerHTML='<div class="spawn-map-dialog"><small>TACTICAL LINK / DEPLOYMENT</small><button id="spawn-map-close">M · Close</button><h2>AREA MAP</h2><canvas width="720" height="440" aria-label="Select a friendly spawn marker"></canvas><p id="spawn-map-status"></p><div id="spawn-map-options"></div></div>';document.body.append(radar,panel);
 let projected=[],lastOptions='',clock=-1;
 function toggle(){panel.hidden=!panel.hidden;if(!panel.hidden)onOpen();update(true);}
 radar.onclick=toggle;panel.querySelector('#spawn-map-close').onclick=toggle;
 function draw(canvas,large){const ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height,scale=Math.min(w/1150,h/760),project=p=>[w/2+p.x*scale,h/2+p.z*scale];ctx.fillStyle='#071b15';ctx.fillRect(0,0,w,h);ctx.lineWidth=1;ctx.strokeStyle='#214c38';for(let i=0;i<w;i+=24){ctx.beginPath();ctx.moveTo(i,0);ctx.lineTo(i,h);ctx.stroke();}for(let j=0;j<h;j+=24){ctx.beginPath();ctx.moveTo(0,j);ctx.lineTo(w,j);ctx.stroke();}
  ctx.strokeStyle='#417455';ctx.lineWidth=60*scale;ctx.beginPath();ctx.arc(w/2,h/2,77.5*scale,0,Math.PI*2);ctx.stroke();ctx.lineWidth=1;
  world.castles.forEach((castle,team)=>{if(!castle.visible)return;const p=world.pads[team],[x,y]=project(p);ctx.strokeStyle=team?'#e18b7b':'#89f5bb';ctx.strokeRect(x-30*scale,y-40*scale,60*scale,80*scale);});
  for(const o of objectives){const [x,y]=project(o);ctx.fillStyle=o.owner<0?'#d4cda3':o.owner?'#e18b7b':'#89f5bb';ctx.fillRect(x-3,y-3,6,6);if(large){ctx.font='12px monospace';ctx.fillText(o.label,x+8,y-5);}}
  for(const a of actors)if(a.alive){const [x,y]=project(a.state);ctx.fillStyle=a.team?'#e86e65':'#99efb5';ctx.beginPath();ctx.moveTo(x,y-4);ctx.lineTo(x+3,y+3);ctx.lineTo(x-3,y+3);ctx.fill();if(a.human){ctx.strokeStyle='#fff';ctx.strokeRect(x-6,y-6,12,12);}}
  projected=[];if(large)for(const p of spawns.points()){const [x,y]=project(p);projected.push({...p,sx:x,sy:y});ctx.strokeStyle=p.id===spawns.selected?'#fff7bd':'#71ffaa';ctx.beginPath();ctx.arc(x,y,8,0,Math.PI*2);ctx.stroke();}
  ctx.fillStyle='#8df3b919';ctx.fillRect(0,(combat.state.time*26)%h,w,12);ctx.fillStyle='#00000025';for(let y=0;y<h;y+=3)ctx.fillRect(0,y,w,1);
 }
 panel.querySelector('canvas').onclick=e=>{const rect=e.currentTarget.getBoundingClientRect(),x=(e.clientX-rect.left)*720/rect.width,y=(e.clientY-rect.top)*440/rect.height,p=projected.slice().sort((a,b)=>Math.hypot(a.sx-x,a.sy-y)-Math.hypot(b.sx-x,b.sy-y))[0];if(p&&Math.hypot(p.sx-x,p.sy-y)<20){spawns.select(p.id);update(true);}};
 function update(force=false){radar.hidden=combat.state.phase==='idle';if(!force&&combat.state.time-clock<.15)return;clock=combat.state.time;draw(radar.querySelector('canvas'),false);if(panel.hidden)return;draw(panel.querySelector('canvas'),true);const points=spawns.points(),key=JSON.stringify(points.map(p=>p.id))+spawns.selected+combat.state.phase;if(key!==lastOptions){lastOptions=key;panel.querySelector('#spawn-map-options').replaceChildren(...points.map(p=>{const b=document.createElement('button');b.textContent=p.label;b.dataset.spawn=p.id;b.setAttribute('aria-pressed',String(p.id===spawns.selected));b.disabled=combat.state.phase!=='running';b.onclick=()=>{spawns.select(p.id);update(true);};return b;}));}const selected=points.find(p=>p.id===spawns.selected)||points[0];panel.querySelector('#spawn-map-status').textContent=combat.state.phase==='evacuation'?'EVACUATION · No respawns. Escape on foot, pod or chariot.':'NEXT RESPAWN: '+(selected?.label||'No safe point')+' · Selection applies after death. Hostile or contested points are unavailable.';}
 return {toggle,update,close(){panel.hidden=true;},get open(){return !panel.hidden;}};
}
